<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue';import {admin,date} from '../../../shared/api';import type {Page} from '../../../shared/types';import {useLoad} from '../../../shared/useLoad';import {ElMessage,ElMessageBox} from 'element-plus'
interface Employee {id:string;username:string;displayName:string;phone:string|null;role:'staff';status:'active'|'disabled';version:number;createdAt:string;passwordChangeAvailableAt:string|null}
const result=ref<Page<Employee>>(),query=reactive({keyword:'',status:''}),dialogOpen=ref(false),editing=ref<Employee>(),passwordEmployee=ref<Employee>(),newPassword=ref(''),form=reactive({username:'',displayName:'',phone:'',password:''}),{loading,error,run}=useLoad()
const load=(page=1)=>run(async()=>{result.value=await admin('GET','/admin/employees',undefined,{keyword:query.keyword||undefined,status:query.status||undefined,page,pageSize:10})})
function edit(employee?:Employee){editing.value=employee;Object.assign(form,{username:employee?.username||'',displayName:employee?.displayName||'',phone:employee?.phone||'',password:''});error.value='';dialogOpen.value=true}
const refresh=async()=>{result.value=await admin('GET','/admin/employees',undefined,{keyword:query.keyword||undefined,status:query.status||undefined,page:result.value?.page||1,pageSize:10})}
const save=()=>run(async()=>{
 const row=editing.value
 await admin(row?'PUT':'POST',row?`/admin/employees/${row.id}`:'/admin/employees',row?{displayName:form.displayName,phone:form.phone||null,version:row.version}:{...form,phone:form.phone||null})
 form.password='';dialogOpen.value=false;ElMessage.success(row?'员工资料已更新':'员工账号已创建');await refresh()
})
async function toggle(row:Employee){
 const disabled=row.status==='active'
 try{await ElMessageBox.confirm(disabled?'停用后，该员工立即退出登录并无法操作后台；历史交付记录会保留。':'重新启用后，该员工需要使用账号密码重新登录。',disabled?'停用员工':'启用员工',{confirmButtonText:disabled?'停用':'启用',cancelButtonText:'取消',type:'warning'})}catch{return}
 await run(async()=>{await admin('PUT',`/admin/employees/${row.id}/status`,{status:disabled?'disabled':'active',version:row.version});ElMessage.success(disabled?'员工已停用':'员工已启用');await refresh()})
}
// 重置成功后清空输入，不回显或保存明文密码；旧登录凭证由服务器撤销。
const resetPassword=()=>run(async()=>{const row=passwordEmployee.value!;await admin('PUT',`/admin/employees/${row.id}/password`,{newPassword:newPassword.value,version:row.version});newPassword.value='';passwordEmployee.value=undefined;ElMessage.success('密码已重置，员工需要重新登录');await refresh()})
function openPassword(row:Employee){passwordEmployee.value=row;newPassword.value='';error.value=''}
function resetAvailable(row:Employee){return !row.passwordChangeAvailableAt||new Date(row.passwordChangeAvailableAt).getTime()<=Date.now()}
onMounted(()=>load())
</script>
<template>
 <div class="section-title"><div><p class="eyebrow">TEAM ACCESS</p><h2>每位同事，各司其职。</h2><p>接待员工可查看预约和宠物档案、办理交付。经营管理由店长负责。</p></div><el-button type="primary" size="large" @click="edit()">新增员工</el-button></div>
 <form class="toolbar" @submit.prevent="load()"><el-input v-model="query.keyword" aria-label="搜索员工" placeholder="姓名 / 账号 / 联系号码" clearable/><el-select v-model="query.status" placeholder="全部状态" clearable @change="load()"><el-option value="active" label="已启用"/><el-option value="disabled" label="已停用"/></el-select><el-button native-type="submit" :loading="loading">查询</el-button></form>
 <el-alert v-if="error&&!dialogOpen&&!passwordEmployee" :title="error" type="error" :closable="false"/>
 <div class="table-panel"><el-table :data="result?.items||[]" v-loading="loading" empty-text="暂无员工，点击新增员工创建接待账号"><el-table-column prop="displayName" label="姓名" min-width="110"/><el-table-column prop="username" label="登录账号" min-width="160"/><el-table-column label="联系号码" min-width="140"><template #default="{row}">{{row.phone||'未填写'}}</template></el-table-column><el-table-column label="角色" min-width="100"><template #default>接待员工</template></el-table-column><el-table-column label="状态" min-width="110"><template #default="{row}"><el-tag :type="row.status==='active'?'success':'info'">{{row.status==='active'?'已启用':'已停用'}}</el-tag></template></el-table-column><el-table-column label="创建时间" min-width="150"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="250" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="loading" @click="edit(row)">编辑</el-button><el-button link :disabled="loading||!resetAvailable(row)" :title="resetAvailable(row)?'重置密码':`下次可修改：${date(row.passwordChangeAvailableAt)}`" @click="openPassword(row)">重置密码</el-button><el-button link :type="row.status==='active'?'danger':'primary'" :disabled="loading" @click="toggle(row)">{{row.status==='active'?'停用':'启用'}}</el-button></template></el-table-column></el-table></div>
 <div class="pagination"><el-pagination v-if="result" layout="prev,pager,next" :total="result.total" :page-size="10" :current-page="result.page" @current-change="load"/></div>
 <el-dialog v-model="dialogOpen" :title="editing?'编辑员工':'新增员工'" width="500px" @closed="form.password=''">
  <el-form label-position="top" @submit.prevent="save"><el-form-item label="登录账号"><el-input v-model="form.username" :disabled="Boolean(editing)||loading" required minlength="3" maxlength="32" autocomplete="off"/><small>3至32位，以字母开头，可包含数字和下划线；创建后固定。</small></el-form-item><el-form-item label="姓名"><el-input v-model="form.displayName" :readonly="loading" required maxlength="30"/></el-form-item><el-form-item label="联系号码（选填）"><el-input v-model="form.phone" :readonly="loading" maxlength="11" inputmode="tel"/></el-form-item><el-form-item v-if="!editing" label="初始密码"><el-input v-model="form.password" :readonly="loading" required minlength="12" maxlength="128" type="password" show-password autocomplete="new-password"/><small>12至128位，包含字母和数字。</small></el-form-item><p class="small muted">角色：接待员工。账号由店长创建，无需员工自行注册。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="actions"><el-button type="primary" native-type="submit" :loading="loading">{{editing?'保存修改':'创建账号'}}</el-button><el-button :disabled="loading" @click="dialogOpen=false">取消</el-button></div></el-form>
 </el-dialog>
 <el-dialog :model-value="Boolean(passwordEmployee)" title="重置员工密码" width="480px" @update:model-value="(value:boolean)=>{if(!value){passwordEmployee=undefined;newPassword=''}}"><p>{{passwordEmployee?.displayName}} · {{passwordEmployee?.username}}</p><p>重置后所有旧登录立即失效。沿用账号规则，密码每7天只能修改一次。</p><el-form label-position="top" @submit.prevent="resetPassword"><el-form-item label="新密码"><el-input v-model="newPassword" :readonly="loading" required minlength="12" maxlength="128" type="password" show-password autocomplete="new-password"/></el-form-item><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="actions"><el-button type="primary" native-type="submit" :loading="loading">重置密码</el-button><el-button :disabled="loading" @click="passwordEmployee=undefined;newPassword=''">取消</el-button></div></el-form></el-dialog>
</template>
